function renderSceneStudio(){const t=audioTime();$('clock').textContent=`${t.toFixed(1)} / 20秒`;$('now-playing').textContent=(config.musicProvenance.label??'Music B')+' · 速度1倍 · 音源1 · OFFLINE保存再生';$('queue-count').textContent='既存4シーン · 生成0 · '+state.phase;$('new-session').disabled=state.phase!=='STOPPED';$('music-control').textContent=`${config.musicProvenance.label??'保存Music B'} / 音楽controlVersion${config.scenes[0].musicControlVersion??0}固定・scene別の再生順`;$('onset-status').textContent=`音の立ち上がり ${pulse?.getMetrics().onsetEvents??0}回 · 保存音声の因果的な脈動`;$('dj-decision').textContent='既存素材の明示playlistで3回の構造切替。音楽の親子キューや生成commitは変更しません。';const current=sceneController?.state().activeScene??-1;$('work-queue').replaceChildren(...config.scenes.map((s,i)=>{const card=document.createElement('article');card.className='card'+(i===current?' active':'');for(const txt of [s.title,i===current&&active?'PLAYING':i<=current?'PLAYED':'READY',`${s.startSeconds}–${s.endSeconds}秒 · 元設定v${s.sourceVersion}`,`元motif: ${s.motifSnapshot.motifId}`,`対応音楽: ${s.musicRef.assetId} / scene再生順${s.playbackRevision}`]){const line=document.createElement('p');line.textContent=txt;card.append(line);}return card;}));}
