$('scene-plan-apply').onclick=async()=>{try{visualPlanState=await call('/api/scene-plan/settings',{expectedPlanVersion:visualPlanState.planVersion,settings:{changeAmount:$('scene-amount').value,intervalSeconds:Number($('scene-interval').value)}});renderStructurePlan();batchPreview=null;$('batch-commit').disabled=true;}catch(e){$('structure-plan-history').textContent='計画変更保留: '+e.message;}};$('scene-plan-preview').onclick=async()=>{try{visualPlanState=await call('/api/scene-plan/preview',{});renderStructurePlan();$('structure-plan-history').textContent+=' 4参照画像・構造別指示・件数・料金を固定保存。要求0。';}catch(e){$('structure-plan-history').textContent=e.message;}};renderStructurePlan();

// Key each review card independently: polling or another result never replaces its video/focus.
function renderBatch(){if(!batchMode)return;const b=batchState?.batch;if(!b)return;
 $('queue-count').textContent=`音楽予約 ${b.counts.music} / 構造映像 ${b.counts.video}/4 · ${b.status}`;
 $('batch-status').textContent=`${studio.providerReplay?'REPLAY・保存providerレスポンス / 実API0・鍵取得0・課金0':studio.kind==='mock'?'OFFLINE保存素材再現 / API0・鍵取得0・課金0':'LIVE・新規結果は人間の構造確認が必要'} / ${b.status} / 音楽予約${b.counts.music}・映像試行${b.counts.video} / 再送なし`;
 $('batch-preview').disabled=stopped||(!active&&!studio.prePlaybackConfirmation)||b.status!=='IDLE'||batchSending;
 $('stop').disabled=stopped||!active&&b.status==='IDLE';if(studio.preparationBeforePlayback){$('start').disabled=stopped||active||b.status!=='READY';$('start').textContent=b.status==='READY'?'確認済みの音楽と4構造で演奏開始':'準備・4構造確認後に演奏を開始';$('apply-settings').disabled=b.status!=='IDLE';$('batch-status').textContent+=active?' / 演奏180秒（演奏開始から）':' / 無音準備・レビュー（音声0秒、演奏180秒を消費しません）';}if(videoOnly)$('start').textContent=b.status==='READY'?'確認した4映像を保存Music Bで再生':'保存Music Bを先に聴く（4件の準備・確認後を推奨）';
 const wanted=new Set();for(const j of b.jobs??[]){wanted.add(j.jobId);const signature=JSON.stringify([b.musicRef?.assetId,j.status,j.attempts,j.reason,j.result?.asset?.sha256,stopped]);let entry=batchCards.get(j.jobId);
 if(legacyReviewUi||!entry||entry.signature!==signature){const c=document.createElement('article');c.className='card';c.dataset.jobId=j.jobId;diagnostics.cardBuilds++;
 for(const text of [j.scene.title,j.status,`試行 ${j.attempts}/1 · scene ${j.scene.playbackRevision} · 設定v${j.scene.musicControlVersion}`,`対応音楽: ${b.musicRef?.assetId??'QC待ち'}`,j.reason??(videoOnly?'完成・照合・構造確認を満たす4件だけを固定Music Bへ採用':'完成・照合・構造確認を満たす4件だけを音楽commit後に採用')]){const p=document.createElement('p');p.textContent=text;c.append(p);}
 if(j.status==='REVIEW_REQUIRED'&&!stopped){const video=document.createElement('video');video.src=j.result.displayAsset?.url??j.result.asset.url;video.controls=true;video.muted=true;video.volume=0;video.style.width='100%';video.addEventListener('loadeddata',()=>{diagnostics.previewLoads++;diagnostic('PREVIEW_LOADED',{jobId:j.jobId});});const button=document.createElement('button');button.textContent='参照と比較し、この構造を採用';button.onclick=async()=>{if(button.disabled||stopped)return;button.disabled=true;diagnostics.reviewClicks++;diagnostic('REVIEW_CLICK',{jobId:j.jobId,audioTime:audioTime()});try{await call('/api/scene-plan/review',{jobId:j.jobId,approved:true,assetSha256:j.result.asset.sha256,sceneSnapshotSha256:j.scene.sceneSnapshotSha256});video.pause();diagnostic('REVIEW_ACK',{jobId:j.jobId});if(!active)void pollPreparation();}catch(e){$('batch-status').textContent=e.message;button.disabled=stopped;}};c.append(video,button);}
 if(entry){entry.element.querySelectorAll('video').forEach(v=>v.pause());entry.element.replaceWith(c);}else $('batch-queue').append(c);entry={element:c,signature};batchCards.set(j.jobId,entry);}}
 for(const [id,entry]of batchCards)if(!wanted.has(id)){entry.element.remove();batchCards.delete(id);}
 if(sceneController&&!batchState.playlist){sceneController.stop();clearInterval(sceneTimer);}
}
// Preparation has no audio callback/tick and therefore consumes none of the finite playback cap.
async function pollPreparation(){if(!batchMode||!studio.prePlaybackConfirmation||active||stopped||prepPolling)return;clearTimeout(prepTimer);prepPolling=true;try{const nextState=await call('/api/state'),nextBatch=await call('/api/scene-plan/batch-state');if(active||stopped)return;state=nextState;batchState=nextBatch;render();renderBatch();if(!['IDLE','PREPARING'].includes(state.phase))await stop(false,state.stopReason??'BACKEND_STOP');}catch(e){$('batch-status').textContent=e.message;diagnostic('PREPARATION_POLL_ERROR',{message:e.message});}finally{prepPolling=false;if(!active&&!stopped)prepTimer=setTimeout(()=>void pollPreparation(),500);}}
