// UI only: existing job, review, audio and frame-source contracts remain authoritative.
// Transport-neutral fixture controller. No provider credentials, playback or version writes.
function createIntentCueController({request,available=false,onChange=()=>{},now=()=>Date.now(),uuid=()=>crypto.randomUUID()}={}) {
 let epoch=0,disposed=false,refreshing=false,submitPromise;
 let state={phase:available?'DRAFT':'UNAVAILABLE',text:'',direction:null,plan:null,clarification:null,error:null,generations:[],cues:[],selectedGenerationId:null,nonce:null,deliveryUnknown:false,updatedAt:null};
 const read=()=>structuredClone(state);
 const emit=()=>{if(!disposed)onChange(read());};
 const patch=v=>{state={...state,...v};emit();};
 const errors={CACHED_PLAYING_CONTEXT_NOT_PREPARED:'現在の保存 Music B の16秒contextは未準備です。別の曲を親として代用せず、今回の試験を保留します。',ACTIVE_CONTINUATION_FIXTURE_NOT_PREPARED:'現在の継続曲に対応するfixtureは未準備です。現在の演奏を維持して保留します。',CUE_SOURCE_STOPPED:'停止済みの曲からは試験できません。新しいセッションで確認してください。',CUE_SOURCE_CHANGED:'確認中に元の曲や設定が変わりました。意図を確認し直してください。',CUE_PLAN_STALE:'確認内容の有効期限または元の状態が変わりました。意図を確認し直してください。',CUE_PLAN_NOT_FOUND:'確認内容が失効しました。意図を確認し直してください。'};
 const errorText=e=>errors[e.code??e.message]??`試験を保留しました: ${e.code??e.message}`;
 function edit(text){if(disposed||state.phase==='SUBMITTING'||state.deliveryUnknown)return false;epoch++;patch({text,direction:null,plan:null,clarification:null,error:null,nonce:null,selectedGenerationId:null,phase:available?'DRAFT':'UNAVAILABLE'});return true;}
 async function preview(direction=state.direction){
  if(!available||disposed||state.phase==='SUBMITTING'||state.deliveryUnknown||!state.text.trim())return;
  const token=++epoch;patch({phase:'CHECKING',plan:null,clarification:null,error:null,direction});
  try{const context=await request('/api/cues/context');if(token!==epoch||disposed)return;
   if(context.mode!=='fixture'||context.llmUsed!==false||context.actualAPIRequests!==0)throw Error('ZERO_COST_FIXTURE_CONTEXT_REQUIRED');
   const p=await request('/api/cues/preview',{text:state.text,expectedSource:context.source,...(direction?{direction}:{})});if(token!==epoch||disposed)return;
   if(p.status==='NEEDS_CLARIFICATION'){patch({phase:'CLARIFY',clarification:p});return;}
   // A local rules preview must never silently become a live/provider command.
   if(p.status!=='COMPILED'||p.mode!=='fixture'||p.llmUsed!==false||p.scope?.actualAPIRequests!==0||p.scope?.actualCostUsd!==0||p.music?.commonIntentSha256!==p.video?.commonIntentSha256)throw Error('FIXTURE_PREVIEW_CONTRACT_REQUIRED');
   patch({phase:'PREVIEW',plan:p,nonce:'fixture_'+uuid().replaceAll('-','_'),error:null});
  }catch(e){if(token===epoch&&!disposed)patch({phase:'HOLD',plan:null,error:errorText(e)});}
 }
 function confirm(){
  if(submitPromise)return submitPromise;
  if(disposed||state.phase!=='PREVIEW'||!state.plan||state.deliveryUnknown)return Promise.resolve();
  if(state.plan.expiresAtMs<=now()){patch({phase:'HOLD',plan:null,error:errors.CUE_PLAN_STALE});return Promise.resolve();}
  const token=epoch,body={planId:state.plan.planId,confirmed:true,nonce:state.nonce};patch({phase:'SUBMITTING',error:null});
  submitPromise=(async()=>{try{
   const g=await request('/api/cues/generate',body);if(disposed||token!==epoch)return;
   if(g.mode!=='fixture'||!g.generationId||g.adopted===true||g.actualAPIRequests!==0)throw Error('FIXTURE_GENERATION_CONTRACT_REQUIRED');
   patch({phase:'PENDING',selectedGenerationId:g.generationId,generations:[...state.generations.filter(x=>x.generationId!==g.generationId),g],plan:null});await refresh();
  }catch(e){if(!disposed){const rejected=e.status===409&&['CUE_PLAN_STALE','CUE_PLAN_NOT_FOUND','CUE_SOURCE_CHANGED','CUE_ORIGIN_REQUIRED','CUE_PREVIEW_REQUIRED','CACHED_PLAYING_CONTEXT_NOT_PREPARED','ACTIVE_CONTINUATION_FIXTURE_NOT_PREPARED','CUE_SOURCE_STOPPED','CUE_SOURCE_NOT_READY','CUE_LEDGER_HOLD'].includes(e.code);patch({phase:rejected?'HOLD':'DELIVERY_UNKNOWN',deliveryUnknown:!rejected,plan:null,error:rejected?errorText(e):'送信結果を確認できません。再送せず、状態の再確認だけを行います。'});}}
  finally{submitPromise=null;}})();return submitPromise;
 }
 async function refresh(){
  if(!available||disposed||refreshing)return;refreshing=true;const token=epoch;
  try{const [a,b]=await Promise.all([request('/api/cues/generations'),request('/api/cues')]);if(disposed||token!==epoch)return;
   const generations=a.generations??[],cues=b.cues??[],found=state.deliveryUnknown?generations.find(g=>g.nonce===state.nonce):generations.find(g=>g.generationId===state.selectedGenerationId);
   const update={generations,cues,updatedAt:now()};
   if(found&&['PENDING','REGISTERED','DELIVERY_UNKNOWN'].includes(state.phase)){update.selectedGenerationId=found.generationId;update.deliveryUnknown=false;const catalogue=cues.find(c=>c.generationId===found.generationId);update.phase=found.state==='REGISTERED'&&catalogue?.status==='READY'?'REGISTERED':found.state==='GENERATING'||found.state==='PARTIAL_READY'?'PENDING':'HOLD';update.error=update.phase==='HOLD'?`セットは保留です: ${catalogue?.status??found.state}`:null;}
   patch(update);
  }catch(e){if(!disposed&&token===epoch)patch({error:'状態を確認できません。最後の状態を保持しています。再送は行いません。'});}
  finally{refreshing=false;}
 }
 async function cancel(id){if(disposed)return;try{await request('/api/cues/generations/'+encodeURIComponent(id)+'/cancel',{});await refresh();}catch(e){patch({error:errorText(e)});}}
 return {read,edit,preview,confirm,refresh,cancel,dispose(){disposed=true;epoch++;}};
}

// Fixture catalogue is separate from actual DJ candidates: target version is future.
function registeredFixtureCues(cues){return(cues??[]).filter(c=>c.mode==='fixture'&&c.status==='READY'&&c.atomicReady===true&&c.actualGenerationThisRun===false&&c.playbackRevision===null&&c.requiresExplicitPlaybackCommit===true&&c.music?.status==='QC_READY'&&c.video?.status==='QC_READY'&&c.music.controlVersion===c.controlVersion&&c.video.controlVersion===c.controlVersion&&c.music.qc?.passed===true&&c.video.qc?.passed===true&&c.video.review?.accepted===true&&c.music.binding?.generationId===c.generationId&&c.video.binding?.generationId===c.generationId&&c.music.binding?.commonIntentSha256===c.commonIntentSha256&&c.video.binding?.commonIntentSha256===c.commonIntentSha256);}

